:root {
  --bg: #2d1b4e;
  --surface: #3e2a6b;
  --primary: #f72585;
  --secondary: #4cc9f0;
  --text: #f8f9fa;
  --card-back: #6a4c93;
  --card-hover: #7b5ea7;
  --win: #b5179e;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 16px;
}

.game-container {
  background: var(--surface);
  border-radius: 24px;
  padding: 24px;
  max-width: 600px;
  width: 100%;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
}

h1 {
  font-size: 1.6rem;
  font-weight: 700;
  letter-spacing: 0.5px;
  color: var(--secondary);
}

.stats {
  font-size: 1.1rem;
  background: rgba(255, 255, 255, 0.1);
  padding: 6px 16px;
  border-radius: 20px;
}

.game-board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  justify-content: center;
}

.card {
  aspect-ratio: 1 / 1;
  border-radius: 12px;
  cursor: pointer;
  transition: transform 0.15s ease, background 0.2s ease, box-shadow 0.2s ease;
  background: var(--card-back);
  border: 2px solid transparent;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.4rem;
  font-weight: 700;
  color: transparent;
  user-select: none;
}

.card:hover:not(.matched):not(.flipped) {
  background: var(--card-hover);
  transform: scale(1.03);
}

.card:focus-visible {
  outline: 3px solid var(--secondary);
  outline-offset: 2px;
}

.card.flipped,
.card.matched {
  background: var(--primary);
  color: var(--text);
  cursor: default;
  transform: none;
}

.card.matched {
  background: var(--win);
  box-shadow: 0 0 12px var(--win);
}

.win-message {
  text-align: center;
  font-size: 1.2rem;
  font-weight: 600;
  min-height: 1.6em;
  color: var(--secondary);
}

.new-game-btn {
  font-family: inherit;
  font-size: 1.1rem;
  font-weight: 600;
  padding: 14px 24px;
  border: none;
  border-radius: 12px;
  background: var(--primary);
  color: var(--text);
  cursor: pointer;
  transition: background 0.2s ease, transform 0.1s ease;
  align-self: center;
  min-width: 180px;
}

.new-game-btn:hover {
  background: #ff4d9e;
}

.new-game-btn:focus-visible {
  outline: 3px solid var(--secondary);
  outline-offset: 2px;
}

.new-game-btn:active {
  transform: scale(0.97);
}

@media (max-width: 480px) {
  body {
    padding: 8px;
    font-size: 16px;
  }
  .game-container {
    padding: 16px;
    border-radius: 16px;
  }
  h1 {
    font-size: 1.3rem;
  }
  .game-board {
    gap: 8px;
  }
  .card {
    border-radius: 8px;
    font-size: 1.1rem;
  }
  .new-game-btn {
    font-size: 1rem;
    padding: 12px 20px;
  }
}

const COLORS = [
  '#e63946', '#f4a261', '#2a9d8f', '#457b9d',
  '#9b5de5', '#f15bb5', '#00bbf9', '#00f5d4'
];

let deck = [];
let flippedCards = [];
let matchedPairs = 0;
let moves = 0;
let lockBoard = false;

const board = document.getElementById('game-board');
const movesDisplay = document.getElementById('moves-display');
const winMessage = document.getElementById('win-message');
const newGameBtn = document.getElementById('new-game-btn');

function shuffle(array) {
  for (let i = array.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [array[i], array[j]] = [array[j], array[i]];
  }
  return array;
}

function createDeck() {
  const pairs = COLORS.flatMap(color => [color, color]);
  return shuffle(pairs);
}

function renderBoard() {
  board.innerHTML = '';
  deck.forEach((color, index) => {
    const card = document.createElement('button');
    card.type = 'button';
    card.className = 'card';
    card.dataset.color = color;
    card.dataset.index = index;
    card.setAttribute('aria-label', 'Hidden card');
    card.addEventListener('click', () => handleCardClick(card));
    board.appendChild(card);
  });
}

function handleCardClick(card) {
  if (lockBoard || card.classList.contains('flipped') || card.classList.contains('matched')) return;

  card.classList.add('flipped');
  card.style.background = card.dataset.color;
  card.setAttribute('aria-label', 'Revealed card');
  flippedCards.push(card);

  if (flippedCards.length === 2) {
    moves++;
    movesDisplay.textContent = `Moves: ${moves}`;
    checkMatch();
  }
}

function checkMatch() {
  const [card1, card2] = flippedCards;
  const isMatch = card1.dataset.color === card2.dataset.color;

  if (isMatch) {
    card1.classList.add('matched');
    card2.classList.add('matched');
    card1.setAttribute('aria-label', 'Matched card');
    card2.setAttribute('aria-label', 'Matched card');
    matchedPairs++;
    flippedCards = [];
    if (matchedPairs === COLORS.length) {
      winMessage.textContent = `You won in ${moves} moves!`;
    }
  } else {
    lockBoard = true;
    setTimeout(() => {
      card1.classList.remove('flipped');
      card2.classList.remove('flipped');
      card1.style.background = '';
      card2.style.background = '';
      card1.setAttribute('aria-label', 'Hidden card');
      card2.setAttribute('aria-label', 'Hidden card');
      flippedCards = [];
      lockBoard = false;
    }, 800);
  }
}

function resetGame() {
  deck = createDeck();
  flippedCards = [];
  matchedPairs = 0;
  moves = 0;
  lockBoard = false;
  movesDisplay.textContent = 'Moves: 0';
  winMessage.textContent = '';
  renderBoard();
}

newGameBtn.addEventListener('click', resetGame);

resetGame();
